<template>
  <div class="dashboard-page" v-loading="loading">
    <header class="hero">
      <div class="hero-copy"><span class="eyebrow"><i></i> AILEX · ADMIN CENTER</span><h1>运营看板</h1><p>让合同审核、风险预警与整改进度一目了然</p></div>
      <div class="hero-action"><span class="sync"><b></b> 数据实时同步 <em v-if="lastUpdated">{{ formatTime(lastUpdated) }}</em></span><div class="hero-tools"><el-radio-group v-model="range" size="small" @change="fetchSummary()"><el-radio-button label="7d">近 7 天</el-radio-button><el-radio-button label="30d">近 30 天</el-radio-button></el-radio-group><el-button class="refresh-button" type="primary" :icon="Refresh" @click="fetchSummary()">刷新数据</el-button></div></div>
      <div class="hero-orb orb-one"></div><div class="hero-orb orb-two"></div>
    </header>
    <el-alert v-if="loadError" type="error" :title="loadError" show-icon :closable="false" class="error-bar"><template #default><el-button link type="primary" @click="fetchSummary()">重新加载</el-button></template></el-alert>

    <section class="top-grid">
      <article class="contract-card">
        <div class="card-glow"></div><div class="card-top"><span class="label">总合同量</span><span class="icon-box"><svg viewBox="0 0 24 24"><path d="M14 3H6a2 2 0 00-2 2v14a2 2 0 002 2h12a2 2 0 002-2V9z"/><path d="M14 3v6h6M8 13h8M8 17h5"/></svg></span></div>
        <strong>{{ number(summary.contractsTotal) }}</strong><div class="contract-footer"><span><b>{{ number(summary.reviewsTotal) }}</b> 审核任务</span><span><b>{{ number(summary.activeUsers) }}</b> 活跃用户</span></div>
      </article>
      <article class="stages-card">
        <div class="card-top"><div><span class="label dark">各阶段审核数量</span><p>审核工作流实时进度</p></div><span class="live-pill">LIVE</span></div>
        <div class="stage-list"><template v-for="(stage, index) in stages" :key="stage.key"><div class="stage-item"><span :class="['stage-icon', stage.color]">{{ stage.icon }}</span><strong>{{ number(stage.count) }}</strong><small>{{ stage.label }}</small></div><div v-if="index < stages.length - 1" class="stage-link"><i></i></div></template></div>
      </article>
    </section>

    <section class="bottom-grid">
      <article class="panel risk-panel">
        <div class="panel-head"><div><span class="panel-title">风险总数分布</span><p>当前有效风险，已排除人工忽略项</p></div><span class="badge-total">共 {{ number(totalRisks) }} 项</span></div>
        <div class="risk-content"><div class="donut" :style="{ background: riskDonutStyle }"><div><strong>{{ number(totalRisks) }}</strong><span>有效风险</span></div></div><div class="risk-list"><div v-for="risk in riskDistribution" :key="risk.key" class="risk-row"><div class="risk-row-head"><span :class="['dot', risk.color]"></span><span>{{ risk.label }}</span><strong>{{ number(risk.count) }}</strong><small>{{ risk.percent }}%</small></div><div class="track"><div :class="['fill', risk.color]" :style="{ width: `${risk.percent}%` }"></div></div></div></div></div>
