<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { Refresh } from '@element-plus/icons-vue'
import { getDashboardSummary } from '@/api/admin'
import type { DashboardSummary } from '@/types'

const blankSummary = (): DashboardSummary => ({ contractsTotal: 0, contractsByStatus: {}, reviewsTotal: 0, reviewsByStatus: {}, reviewsByStage: {}, effectiveRisksByLevel: {}, pendingLegalReview: 0, pendingRiskReview: 0, completedReviews: 0, warningsTotal: 0, warningsByStatus: {}, overdueWarnings: 0, activeUsers: 0, reportsByStatus: {}, contractUploadTrend: [] })
const summary = ref<DashboardSummary>(blankSummary())
const loading = ref(false); const loadError = ref(''); const lastUpdated = ref(''); const range = ref<'7d' | '30d'>('7d')
let timer: ReturnType<typeof setInterval> | null = null
const stages = computed(() => [{ key: 'pending', label: '待处理', count: summary.value.reviewsByStatus?.pending || 0, color: 'gray', icon: '1' }, { key: 'ai', label: 'AI 审核', count: summary.value.reviewsByStage?.aiReview || 0, color: 'blue', icon: '2' }, { key: 'legal', label: '法务审核', count: summary.value.reviewsByStage?.legalReview || 0, color: 'purple', icon: '3' }, { key: 'risk', label: '风控审核', count: summary.value.reviewsByStage?.riskReview || 0, color: 'orange', icon: '4' }, { key: 'completed', label: '已完成', count: summary.value.completedReviews || 0, color: 'green', icon: '✓' }])
const totalRisks = computed(() => Object.values(summary.value.effectiveRisksByLevel || {}).reduce((sum, value) => sum + Number(value || 0), 0))
const riskDistribution = computed(() => { const data = summary.value.effectiveRisksByLevel || {}; const total = totalRisks.value || 1; return [{ key: 'critical', label: '严重风险', count: data.critical || 0, color: 'red', hex: '#ed5b68' }, { key: 'high', label: '高风险', count: data.high || 0, color: 'orange', hex: '#ff9b45' }, { key: 'medium', label: '中风险', count: data.medium || 0, color: 'amber', hex: '#f1bf50' }, { key: 'low', label: '低风险', count: data.low || 0, color: 'green', hex: '#42c98a' }].map(item => ({ ...item, percent: Math.round(Number(item.count) / total * 100) })) })
const riskDonutStyle = computed(() => { let at = 0; const segments = riskDistribution.value.map(item => { const next = at + item.percent; const value = `${item.hex} ${at}% ${next}%`; at = next; return value }); return `conic-gradient(${segments.join(', ') || '#eef2f6 0 100%'})` })
const warnings = computed(() => { const data = summary.value.warningsByStatus || {}; return [{ key: 'pendingLegal', label: '待法务确认', count: data.pendingLegal || 0, color: 'blue' }, { key: 'pendingRisk', label: '待风控确认', count: data.pendingRisk || 0, color: 'purple' }, { key: 'active', label: '整改中', count: data.active || 0, color: 'orange' }, { key: 'processing', label: '整改复审中', count: data.processing || 0, color: 'green' }] })
function number(value: unknown) { return Number(value || 0).toLocaleString() }
function formatTime(value: string) { return new Date(value).toLocaleString('zh-CN') }
function queryRange() { const to = new Date(); const from = new Date(to); from.setDate(from.getDate() - (range.value === '7d' ? 6 : 29)); from.setHours(0, 0, 0, 0); return { from: from.toISOString(), to: to.toISOString() } }
async function fetchSummary(silent = false) { if (!silent) loading.value = true; loadError.value = ''; try { summary.value = { ...blankSummary(), ...(await getDashboardSummary(queryRange())) }; lastUpdated.value = new Date().toISOString() } catch (error: any) { if (!silent) loadError.value = error.response?.data?.message || '运营数据加载失败，请确认后端服务和管理员权限。' } finally { if (!silent) loading.value = false } }
onMounted(() => { fetchSummary(); timer = setInterval(() => fetchSummary(true), 15000) })
onUnmounted(() => { if (timer) clearInterval(timer) })
</script>

